// dashboardPatchWithConflictRetry issues a dashboards instance PATCH with a
// small bounded retry on HTTP 409: the dashboards PATCH path (layout writes,
// content create/delete) is known to return transient conflicts when
// concurrent edits touch the same board, and the shared client only retries
// 5xx/429. 3 attempts, linear backoff (1s, 2s). Shared with the bookmark
// resource's board-report content lifecycle (bookmark_resource.go).
func dashboardPatchWithConflictRetry(ctx context.Context, c *client.Client, path string, body map[string]any) ([]byte, error) {
	const attempts = 3
	var lastErr error
	for i := 0; i < attempts; i++ {
		if i > 0 {
			select {
			case <-ctx.Done():
				return nil, ctx.Err()
			case <-time.After(time.Duration(i) * time.Second):
			}
		}
		respBody, err := c.Do(ctx, "PATCH", path, body)
		if err == nil {
			return respBody, nil
		}
		lastErr = err
		if apiErr, ok := err.(*client.APIError); !ok || apiErr.StatusCode != 409 {
			return nil, err
		}
	}
	return nil, lastErr
}

// dashboardLayoutWriteFormat converts the dashboards GET layout shape
//
//	{"rows": {"<row_id>": {"height": N, "cells": [{"id": ..., "width": N,
//	 "content_id": ..., "content_type": ...}]}}, "order": [...], "version": "2.0.0"}
//
// into the PATCH WRITE format the `layout` attribute carries
//
//	{"rows": [{"id": ..., "height": N, "cells": [{"id": ..., "width": N}]}],
//	 "rows_order": [...]}
//
// so refresh and drift detection compare like with like. Rows are ordered by
// the GET `order` list; rows absent from `order` are appended in sorted-id
// order so no data is dropped. `version` and the cell content pointers
// (content_id/content_type — server-managed enrichment) are stripped; cells
// keep only {id, width}. Returns ok=false on any unexpected shape, in which
// case the caller keeps the prior state instead of erroring.
func dashboardLayoutWriteFormat(v any) (map[string]any, bool) {
	m, ok := v.(map[string]any)
	if !ok {
		return nil, false
	}
	rows, ok := m["rows"].(map[string]any)
	if !ok {
		return nil, false
	}
	var order []any
	if o, present := m["order"]; present && o != nil {
		if order, ok = o.([]any); !ok {
			return nil, false
		}
	}
	outRows := make([]any, 0, len(rows))
	appendRow := func(id string, rowAny any) bool {
		row, ok := rowAny.(map[string]any)
		if !ok {
			return false
		}
		outRow := map[string]any{"id": id}
		if h, present := row["height"]; present && h != nil {
			outRow["height"] = h
		}
		cells := []any{}
		switch cl := row["cells"].(type) {
		case nil:
		case []any:
			for _, c := range cl {
				cm, ok := c.(map[string]any)
				if !ok {
					return false
				}
				oc := map[string]any{}
				if cid, present := cm["id"]; present && cid != nil {
					oc["id"] = cid
				}
				if wd, present := cm["width"]; present && wd != nil {
					oc["width"] = wd
				}
				cells = append(cells, oc)
			}
		default:
			return false
		}
		outRow["cells"] = cells
		outRows = append(outRows, outRow)
		return true
	}
	seen := map[string]bool{}
	for _, ro := range order {
		rid, ok := ro.(string)
		if !ok {
			return nil, false
		}
		rowAny, present := rows[rid]
		if !present {
			continue // stale order entry; drop it
		}
		if !appendRow(rid, rowAny) {
			return nil, false
		}
		seen[rid] = true
	}
	rest := make([]string, 0, len(rows))
	for rid := range rows {
		if !seen[rid] {
			rest = append(rest, rid)
		}
	}
	sort.Strings(rest)
	for _, rid := range rest {
		if !appendRow(rid, rows[rid]) {
			return nil, false
		}
	}
	rowsOrder := make([]any, 0, len(outRows))
	for _, row := range outRows {
		rowsOrder = append(rowsOrder, row.(map[string]any)["id"])
	}
	return map[string]any{"rows": outRows, "rows_order": rowsOrder}, true
}

